package vn.tuan.controller;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import java.security.Principal;import vn.tuan.service.*;
@Controller @RequiredArgsConstructor public class HomeController {
 private final CatalogService catalog;private final StorefrontService storefront;
 @GetMapping({"/","/home","/catalog"}) public String home(@RequestParam(required=false)String keyword,@RequestParam(required=false)Integer categoryId,@RequestParam(required=false)Integer shopId,@RequestParam(defaultValue="new")String sort,@RequestParam(defaultValue="0")int page,Model m,Principal p){var result=catalog.search(keyword,categoryId,shopId,sort,p==null,page);m.addAttribute("productPage",result);m.addAttribute("currentPage",Math.max(0,page));m.addAttribute("totalPages",result.getTotalPages());m.addAttribute("keyword",keyword);m.addAttribute("categoryId",categoryId);m.addAttribute("shopId",shopId);m.addAttribute("sort",sort);m.addAttribute("isAuthenticated",p!=null);if(p!=null)m.addAttribute("currentUser",p.getName());m.addAttribute("categories",storefront.categories());m.addAttribute("shops",storefront.activeShops());return "index";}
}
